//! QOP Desktop: a linked-device qop client. The library holds everything but the UI, so tests
//! and tools can drive it headless.
//!
//! `wire` and `registry` are pure ports of the TS identity/protocol subset a linked device
//! needs. TypeScript stays the source of truth: the golden vectors in `tests/vectors`
//! (generated by `cli/scripts/desktop-vectors.ts`) pin both implementations to the same bytes
//! and the same accept/reject decisions.
//!
//! Around them: `config` (endpoints), `store` and `keys` (local state and the device key),
//! `node` (the minip2p thread), `rpc` and `api` (chain and API reads), and `engine`, the state
//! machine that ties them together and publishes `model::Model` for the UI.

pub mod api;
pub mod config;
pub mod engine;
pub mod keys;
pub mod model;
pub mod node;
pub mod registry;
pub mod rpc;
pub mod store;
pub mod wire;
